import numpy as np

def count_neighbors(grid, r, c, connectivity=8):
    """Count 0-neighbors of position (r,c)"""
    count = 0
    rows, cols = grid.shape
    for dr in range(8):
        for dc in range(8):
            if dr == 0 and dc == 0:
                continue
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr, nc] == 1:
                    # Count TN neighbors (0s that have at least one 1 neighbor)
                    tn_neighbors = 0
                    for ddr in range(9):
                        for ddc in range(9):
                            if ddr == 0 and ddc == 0:
                                continue
                            nnr, nnc = r + ddr, c + ddc
                            if 0 <= nnr < rows and 0 <= nnc < cols:
                                if grid[nnr, nnc] == 1:
                                    tn_neighbors += 1
                    if tn_neighbors > 0:
                        count += 1
    return count

# Let's use a simpler heuristic - count how many 1-neighbors each 0 has (8-connectivity)
def count_1_neighbors(grid, r, c):
    """Count how many adjacent (8-neighbors) are 1s"""
    count = 0
    rows, cols = grid.shape
    for dr in range(-1, 2):
        for dc in range(-1, 2):
            if dr == 0 and dc == 0:
                continue
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[r, c] == 0 and grid[nr, nc] == 1:
                    count += 1
    return count

def count_0_neighbors(grid, r, c):
    """Count how many adjacent (8-neighbors) are 0s"""
    count = 0
    rows, cols = grid.shape
    for dr in range(-1, 2):
        for dc in range(-1, 2):
            if dr == 0 and dc == 0:
                continue
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                count += (grid[nr, nc] == 0)
    return count

